24	/*
25	 * Send an interrupt to process.
26	 *
27	 * Stack is set up to allow trampoline code stored at u.u_sigtramp (as
28	 * specified by the user process) to call the user's real signal catch
29	 * routine, followed by sys sigreturn to the sigreturn routine below
30	 * (see lib/libc/arm/sys/sigaction.S).  After sigreturn resets the signal
31	 * mask, the stack, and the frame pointer, it returns to the user specified
32	 * pc and regs.
33	 */
34	void
35	sendsig(sig_t p, int sig, long mask)
36	{
37		/*
38		 * The exception return that enters the handler pops an eight-word
39		 * frame (r0-r3, r12, lr, pc, xPSR; ARMv6-M ARM B1.5.6) from the
40		 * PSP the kernel sets in tf_sp. That frame is written at sfp, so
41		 * sf_hwframe reserves its 32 bytes and the saved context starts
42		 * above it. A four-word gap here let the hardware frame land on
43		 * sc_onstack, sc_mask, sc_r0 and sc_r1, so every sigreturn restored
44		 * the trampoline address as the signal mask and the handler address
45		 * as r0. sizeof(struct sigframe) is 104, a multiple of eight, so a
46		 * frame carved from an eight-byte-aligned tf_sp keeps AAPCS
47		 * alignment at the handler entry.
48		 */
49		struct sigframe {
50			u_int	sf_hwframe[8];
51			struct	sigcontext sf_sc;
52		};
53	
54		struct trapframe *regs = u.u_frame;
55		struct sigframe *sfp;
56		int oonstack;
57	
58	#ifdef DIAGNOSTIC
59		printf("(%u)sendsig %d, mask=%#x, handler=%#x, tramp=%#x\n",
60		    u.u_procp->p_pid, sig, mask, p, u.u_sigtramp);
61	#endif
62		oonstack = u.u_sigstk.ss_flags & SA_ONSTACK;
63	
64		/*
65		 * Allocate and validate space for the signal frame.
66		 */
67		if ((u.u_psflags & SAS_ALTSTACK) &&
68		    !(u.u_sigstk.ss_flags & SA_ONSTACK) &&
69		    (u.u_sigonstack & sigmask(sig))) {
70			sfp = (struct sigframe *)(((u_int)u.u_sigstk.ss_base +
71			    u.u_sigstk.ss_size) & ~7U);
72			u.u_sigstk.ss_flags |= SA_ONSTACK;
73		} else
74			sfp = (struct sigframe *)(regs->tf_sp & ~7U);
75	
76		sfp--;
77		if (!(u.u_sigstk.ss_flags & SA_ONSTACK)) {
78			if ((caddr_t)sfp < (caddr_t)u.u_procp->p_daddr + u.u_dsize) {
79				/*
80				 * Process has trashed its stack; give it an illegal
81				 * instruction violation to halt it in its tracks.
82				 */
83				fatalsig(SIGILL);
84				return;
85			}
86			if (u.u_procp->p_ssize < USER_TOP(u.u_procp) - (u_int)sfp) {
87				u.u_procp->p_ssize = USER_TOP(u.u_procp) - (u_int)sfp;
88				u.u_procp->p_saddr = (u_int)sfp;
89				u.u_ssize = u.u_procp->p_ssize;
90			}
91		}
92	
93		/*
94		 * Build the signal context to be used by sigreturn.
95		 */
96		sfp->sf_sc.sc_onstack = oonstack;
97		sfp->sf_sc.sc_mask = mask;
98		sfp->sf_sc.sc_r0  = regs->tf_r0;
99		sfp->sf_sc.sc_r1  = regs->tf_r1;
100		sfp->sf_sc.sc_r2  = regs->tf_r2;
101		sfp->sf_sc.sc_r3  = regs->tf_r3;
102		sfp->sf_sc.sc_sp  = regs->tf_sp;
103		sfp->sf_sc.sc_lr  = regs->tf_lr;
104		sfp->sf_sc.sc_pc  = regs->tf_pc;
105		sfp->sf_sc.sc_psr = regs->tf_psr;
106		sfp->sf_sc.sc_r4  = regs->tf_r4;
107		sfp->sf_sc.sc_r5  = regs->tf_r5;
108		sfp->sf_sc.sc_r6  = regs->tf_r6;
109		sfp->sf_sc.sc_r7  = regs->tf_r7;
110		sfp->sf_sc.sc_r8  = regs->tf_r8;
111		sfp->sf_sc.sc_r9  = regs->tf_r9;
112		sfp->sf_sc.sc_r10 = regs->tf_r10;
113		sfp->sf_sc.sc_r11 = regs->tf_r11;
114	
115		/* Call signal handler. */
116		regs->tf_r0 = sig;			/* $a1 - signal number */
117		regs->tf_r1 = u.u_code;			/* $a2 - code */
118		regs->tf_r2 = (int)&sfp->sf_sc;		/* $a3 - addr of sigcontext */
119		regs->tf_lr = (int)u.u_sigtramp;	/* $lr - sigtramp */
120		regs->tf_sp = (int)sfp;			/* $sp - stack */
121		regs->tf_pc = (int)p;			/* $pc - handler */
122		/*
123		 * The original xPSR is in sc_psr. The frame popped into the
124		 * handler must not carry STKALIGN (xPSR bit 9), or the exception
125		 * return adds four to sp (ARMv6-M ARM B1.5.8) and the handler
126		 * starts on a misaligned stack; sigreturn restores sc_psr, so the
127		 * interrupted context gets its own adjustment back.
128		 */
129		regs->tf_psr &= ~XPSR_STKALIGN;
130	
131		if (SYSTRACE_ON(SYSTRACE_SIGNAL))
132			printf("[%u] sendsig %d handler=%#x frame=%#x sc=%#x "
133			    "from pc=%#x sp=%#x psr=%#x mask=%#x\n",
134			    u.u_procp->p_pid, sig, (u_int)p, (u_int)sfp,
135			    (u_int)&sfp->sf_sc, sfp->sf_sc.sc_pc, sfp->sf_sc.sc_sp,
136			    sfp->sf_sc.sc_psr, (u_int)mask);
137	#ifdef DIAGNOSTIC
138		printf("    ...call handler %p (sig=%d, code=%#x, context=%p)\n",
139		    p, sig, u.u_code, &sfp->sf_sc);
140		printf("    ...stack=%p, return to %p\n", sfp, u.u_sigtramp);
141	#endif
142	}
143	
144	/*
145	 * System call to cleanup state after a signal
146	 * has been taken.  Reset signal mask and
147	 * stack state from context left by sendsig (above).
148	 * Return to previous pc and ps as specified by
149	 * context left by sendsig. Check carefully to
150	 * make sure that the user has not modified the
151	 * ps to gain improper priviledges or to cause
152	 * a machine fault.
153	 */
154	void
155	sigreturn(void)
156	{
157		struct trapframe *regs = u.u_frame;
158		/*
159		 * sigtramp issues the sigreturn SVC with sp at the handler entry
160		 * value, sfp + 32, and the SVC entry pushes its own eight-word
161		 * frame there, so tf_sp is sfp again and the context sits past
162		 * sf_hwframe.
163		 */
164		struct sigcontext *scp =
165		    (struct sigcontext *)(regs->tf_sp + 32);
166	
167	#ifdef DIAGNOSTIC
168		printf("(%u)sigreturn stack=%#x, context=%p\n",
169		    u.u_procp->p_pid, regs->tf_sp, scp);
170	#endif
171		if (baduaddr((caddr_t)scp) ||
172		    baduaddr((caddr_t)scp + sizeof(*scp))) {
173			u.u_error = EFAULT;
174			return;
175		}
176		u.u_error = EJUSTRETURN;
177		if (scp->sc_onstack & SA_ONSTACK)
178			u.u_sigstk.ss_flags |= SA_ONSTACK;
179		else
180			u.u_sigstk.ss_flags &= ~SA_ONSTACK;
181		u.u_procp->p_sigmask = scp->sc_mask & ~sigcantmask;
182	
183		if (SYSTRACE_ON(SYSTRACE_SIGNAL))
184			printf("[%u] sigreturn sc=%#x to pc=%#x sp=%#x psr=%#x "
185			    "mask=%#x onstack=%d\n", u.u_procp->p_pid, (u_int)scp,
186			    scp->sc_pc, scp->sc_sp, scp->sc_psr, (u_int)scp->sc_mask,
187			    scp->sc_onstack);
188	
189		/* Return from signal handler. */
190		regs->tf_r0  = scp->sc_r0;
191		regs->tf_r1  = scp->sc_r1;
192		regs->tf_r2  = scp->sc_r2;
193		regs->tf_r3  = scp->sc_r3;
194		regs->tf_sp  = scp->sc_sp;
195		regs->tf_lr  = scp->sc_lr;
196		regs->tf_pc  = scp->sc_pc;
197		regs->tf_psr = scp->sc_psr;
198		regs->tf_r4  = scp->sc_r4;
199		regs->tf_r5  = scp->sc_r5;
200		regs->tf_r6  = scp->sc_r6;
201		regs->tf_r7  = scp->sc_r7;
202		regs->tf_r8  = scp->sc_r8;
203		regs->tf_r9  = scp->sc_r9;
204		regs->tf_r10 = scp->sc_r10;
205		regs->tf_r11 = scp->sc_r11;
206	#ifdef DIAGNOSTIC
207		printf("    ...to %#x, stack %#x\n", regs->tf_pc, regs->tf_sp);
208	#endif
209	}
210	

